}

function inferLocation(input) {
  const text = String(first(input.location, input.city, input.query, input.text, '')).trim();
  const explicit = String(first(input.location, input.city, '')).trim();
  if (explicit) return explicit;

  const match = text.match(/(?:在|查一下|查询)?([\u4e00-\u9fa5A-Za-z\s.-]{2,40})(?:今天|明天|后天|未来|天气|温度|下雨|降雨|会不会|多少度)/);
  if (match && match[1]) {
    const location = match[1].replace(/^(我想知道|请问|帮我看|帮我查|查询|查一下|在)/, '').trim();
    if (location && !/^(今天|明天|未来|天气)$/.test(location)) return location;
  }

  return '香港';
}

function weatherCodeLabel(code) {
  const labels = {
    0: '晴朗',
    1: '大致晴朗',
    2: '局部多云',
    3: '阴天',
    45: '有雾',
    48: '雾凇',
    51: '小毛毛雨',
    53: '中等毛毛雨',
    55: '强毛毛雨',
    61: '小雨',
    63: '中雨',
    65: '大雨',
    71: '小雪',
    73: '中雪',
    75: '大雪',
    80: '小阵雨',
    81: '中等阵雨',
    82: '强阵雨',
    95: '雷雨',
    96: '雷雨伴小冰雹',
    99: '雷雨伴大冰雹',
  };
  return labels[code] || '未知';
}

const input = parseMaybeJson(query);
const locationName = inferLocation(input);
const geoUrl = 'https://geocoding-api.open-meteo.com/v1/search?name='
  + encodeURIComponent(locationName)
  + '&count=1&language=zh&format=json';

const geoResponse = await fetch(geoUrl);
if (!geoResponse.ok) {
  return JSON.stringify({ ok: false, error: 'geocoding_failed', status: geoResponse.status, location: locationName });
}

const geo = await geoResponse.json();
const place = geo.results && geo.results[0];
if (!place) {
  return JSON.stringify({ ok: false, error: 'location_not_found', location: locationName });
}

const forecastUrl = 'https://api.open-meteo.com/v1/forecast'
  + '?latitude=' + encodeURIComponent(place.latitude)
  + '&longitude=' + encodeURIComponent(place.longitude)
  + '&current=temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,rain,weather_code,wind_speed_10m'
  + '&hourly=temperature_2m,precipitation_probability,precipitation,weather_code'
  + '&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,weather_code'
  + '&timezone=auto&forecast_days=3';

const forecastResponse = await fetch(forecastUrl);
if (!forecastResponse.ok) {
  return JSON.stringify({ ok: false, error: 'forecast_failed', status: forecastResponse.status, location: locationName });
}

const forecast = await forecastResponse.json();
const current = forecast.current || {};
const daily = forecast.daily || {};

const days = (daily.time || []).map((date, index) => ({
  date,
  weather: weatherCodeLabel(daily.weather_code && daily.weather_code[index]),
  temperature_min_c: daily.temperature_2m_min && daily.temperature_2m_min[index],
  temperature_max_c: daily.temperature_2m_max && daily.temperature_2m_max[index],
  precipitation_probability_max_percent: daily.precipitation_probability_max && daily.precipitation_probability_max[index],
  precipitation_sum_mm: daily.precipitation_sum && daily.precipitation_sum[index],
}));

return JSON.stringify({
  ok: true,
  provider: 'Open-Meteo',
  requested_location: locationName,
  resolved_location: {
    name: place.name,
    country: place.country,
    admin1: place.admin1,
    latitude: place.latitude,
    longitude: place.longitude,
    timezone: forecast.timezone,
  },
  current: {
    time: current.time,
    weather: weatherCodeLabel(current.weather_code),
    temperature_c: current.temperature_2m,
    apparent_temperature_c: current.apparent_temperature,
    relative_humidity_percent: current.relative_humidity_2m,
    precipitation_mm: current.precipitation,
    rain_mm: current.rain,
    wind_speed_kmh: current.wind_speed_10m,
  },
  daily: days,
  guidance: '请基于 current 和 daily 字段，用中文回答用户，并在需要时输出 Markdown 表格。',
});

